#!/usr/bin/env python3
"""Render draft model review appendices from metadata; never touches source records or a database."""
import collections,csv,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
 model=json.loads((ROOT/'docs/evidence/optimized-model-draft.json').read_text());p=json.loads((ROOT/'docs/evidence/data-profile.json').read_text());summary=json.loads((ROOT/'docs/evidence/model-mapping-summary.json').read_text());tables=model['tables'];by={t['name']:t for t in tables}
 raw=['# Stage 2 — Raw versus organized model','', '**DRAFT — structural comparison, not an approved schema.**','',
 '## Model A: actual raw source structure','',
 'Twelve spreadsheets contain 155 heterogeneous worksheets, not 155 proven entities or database tables. Counts, schemas, source IDs and row references come from frozen Stage 1 evidence. The raw structure includes 6,521 recognized candidate rows, alternate views, formula templates, reports and supporting prose. It is not a unique-record total.','',
 '| Source | Raw shape and important fields | Candidate rows / worksheets | Raw identity / relationship | Repetition and limitations |','| --- | --- | --- | --- | --- |']
 roles={'S01':('Questionnaire A:D context, E:AI items, AJ:AY derived scores, AZ:BA IDs','Explicit child/caregiver IDs match the source link','27 numeric columns plus text/recommendation; views overlap; 60 names disagree'), 'S02':('PT named rosters, monthly P/A date grids, annual reports','Names/program, no approved master crosswalk','Dates repeated as columns and same names repeated by month'), 'S03':('Child register B/C identity, D:F programs/status, personal fields, five promotion pairs; fee/history/sibling/severity sheets','371 unique admissions; parent contacts are role-labelled columns','Repeated names; mixed types; sibling header-only; supplements/reports overlap'), 'S04':('Speech named rosters and monthly P/A grids','Name-based candidates only','Date/header issues and repeated month layouts'), 'S05':('Support matrices, explicit caregiver/child link, aggregate event summary','716 unique caregiver codes; 370 child IDs match admissions','Counts/M/F/Yes are not one universal attendance code'), 'S06':('OT fine-motor named rosters and monthly grids','Name/program only in observations','Blank date slots do not mean absent'), 'S07':('PVSW grid, TRAINEE NAME columns, activity notes and annual view','Trainee-name population/crosswalk unapproved','350 rows were absent from prior name-link coverage; now compared separately'), 'S08':('EI rosters, monthly date grids and visit/activity tables','Name/batch/context, not a global FK','Some observations lack recognized date headings'), 'S09':('FA rosters, monthly grids and activity log','Name/batch, no approved crosswalk','Formula templates inflate dimensions; activity rows need grain review'), 'S10':('Nursery rosters, grids, visit/plan tables and annual view','Name/batch, unresolved activity key','21 repeated description-row excess may be legitimate plans'), 'S11':('Vision attendance rosters/grids/annual view and empty sheet','Name/program only','Empty tab and formatting rows are source structure, not records'), 'S12':('Five Visit flag/date pairs per monthly child row, annual visits/goals','Child name/program, not an approved visit/person key','194 true slots; four undated; false flags not events')}
 for source in p['sources']:
  r=roles[source['source']];raw.append(f"| {source['source']} | {r[0]} | {source['source_record_rows']} / {source['worksheets']} | {r[1]} | {r[2]} |")
 raw+=['','[Worksheet inventory](source-worksheets.md) gives all 155 tabs and native IDs. [Column profiles](evidence/field-profiling.csv) cover 5,044 statistical field instances; the review adds 142 header-only/coordinate slots to account for every one of the 5,186 source column positions. Eight worksheets have no detected record header; their prose/cells remain source payloads, not invented domain fields. Empty and all-formula rows are retained/reconciled separately.','',
 '## Model B: draft organized relational structure','',
 '17 proposed tables (16 core plus conditional activity_logs), with no database created. The original 12-entity conceptual model remains available in the archive and Git baseline. Of the 17, 13 are domain/lookup components and four support source versioning, staging, typed provenance and authenticated access membership. Supabase-managed auth.users is external to this count.','',
 '| Table | Record grain | Why it exists |','| --- | --- | --- |']
 for t in tables:raw.append(f"| {t['name']}{' (conditional)' if t['optional'] else ''} | {t['grain']} | {t['purpose']} |")
 raw+=['','Internal UUIDs decouple database identity from unapproved/reusable source identifiers. Domain FKs use resolved keys; raw source IDs/strings are preserved and never cast directly to UUIDs. Questionnaire responses reference a child-caregiver association, while answers carry definition-consistent response/item FKs. Source-scoped reference values control dropdowns without conflating program, batch, service or role. Imports receive immutable file/row/cell provenance; manual entry uses authenticated audit identity.','',
 '## Comparison and information preservation','',
 'All raw columns and header coordinates have a declared retention location: source_records.cell_payload plus source_artifacts.worksheet_manifest and the protected immutable export. This does not mean every field has a typed curated destination. The full matrix contains 3,366 conditional named operational projections and 1,820 positions with no named business projection. Those 1,820 positions, including derived scores/views, unused structure, sibling templates, summaries and conditional activities, are explicitly listed; none is silently dropped. Any required application field among them blocks workflow approval until a projection is agreed.','',
 'Preserve snapshots before transformation, namespace identifiers, unpivot repeated date/visit/question/promotion columns, and keep distinct observation grains. Do not auto-union source views, deduplicate names, create missing dates, recompute disputed scores, or conflate source retention with approved operational readiness. Technical keys, audit fields and authentication configuration are explicitly proposed system metadata, not new NGO business facts.','',
 'See [structural decision/mapping matrix](12-data-model-comparison-matrix.md), [optimized schema specification](11-optimized-data-model.md) and [decision register](13-data-quality-decision-register.md).']
 (ROOT/'docs/10-raw-vs-organized-model.md').write_text('\n'.join(raw)+'\n')
 specs=['# Stage 2 — Optimized relational model','', '**DRAFT — recommendations only; analyst approval required before Supabase implementation.**','',
 '## Proposed scope and counts','',
 'The full draft has **17 tables**, including **16 core** and **1 conditional** table (`activity_logs`). The original conceptual model had 12 entities and omitted implemented source/access infrastructure. The net additions are one restricted child profile and four provenance/access support tables; PROGRAM is replaced one-for-one with reference_values. No domain was merged merely to lower the count. Auth.users is Supabase-managed and is excluded from the count.','',
 'For the 16-table variant, defer activity_logs together with its optional typed provenance column/FK/index/target group. Retain its raw records and metadata. Do not leave an FK referencing an absent optional table. Other possible future tables—sibling people, support events, clinical dictionaries, rich questionnaire lifecycle, audit-event history—are not in this draft and require approved workflows.','',
 '## Shared design rules','',
 '- UUID PKs are proposed system identities. Source codes remain text in their namespace. A source ID match is not a UUID cast or approval of name authority.','- Server-managed created_at/updated_at are timestamptz. Created_by/updated_by reference auth.users when known; imports may have null historical user with a trusted import actor_ref. Never invent an auth user. Manual writes require the real authenticated actor.','- Mutable domain rows have technical origin_kind and review_state. Unresolved source rows stay in source_records; specific allowed undated imported observations must be marked pending and traceable.','- Required fields shown below are draft database recommendations. Observed completeness does not establish a business mandatory rule. Business requiredness, source-code stability, clinical/financial ranges and canonical categories remain approval gates.','- Dates are date where day-grain is intended; timestamps are timestamptz. Phone numbers, identifiers, codes and leading zeros are text. Money may use a reviewed numeric precision (candidate numeric(14,2)); reported mixed/unknown values remain text or staged. No silent coercion.','- Lookup discriminator columns are fixed/server-generated. MATCH SIMPLE composite vocabulary/code FKs permit an unknown code NULL but cannot link a program field to a role/centre code. Technical enums/check states may be fixed; NGO values use reviewed reference rows, not hardcoded invented enums.','- Questionnaire definition_key is an approved/fingerprinted item-definition namespace, not a source-file export hash and not a new indicator. It is controlled through reference_values without a premature questionnaire-engine table.','- All business and source tables are private by default under RLS/permissions. Children and caregivers still contain personal names. child_private_profiles has a stricter grant/view/RPC boundary; row security alone does not implement field-level protection.','- Source artifacts and source-record payloads are immutable evidence; status/diagnostic updates are separately audited. In this pilot only sanitized authorized payloads may be loaded into any future test project. Original exports remain protected outside Git. No data loading is authorized now.','- Every imported target requires provenance before transaction promotion. The proposed source_provenance table uses bounded typed FK targets, exactly one target group per link, not unconstrained polymorphic entity IDs. This supports multiple source contributions with real FK checks. Server validation enforces source/target field membership. A deferred constraint trigger/import transaction gate is required; a nullable origin string alone is insufficient.','- No cascading deletion of source/person/history evidence. Prefer deactivation/archiving under an approved retention policy; no manual child deletion policy is invented.','- Index candidates below remove identical/prefix duplicates already covered by PK/unique or longer planned indexes. Final query plans/write costs must be checked on the installed PostgreSQL version after approval; no measured performance claim is made.','',
 '## Table-by-table specification','']
 for t in tables:
  specs += ['### '+t['name']+(' — conditional' if t['optional'] else ''),'',t['purpose']+'. **Grain:** '+t['grain']+'.','', '**Primary key:** '+', '.join(t['primary_key'])+'.',
   '**Candidate unique constraints:** '+('; '.join('('+', '.join(x)+')' for x in t['unique_keys']) or 'No additional business uniqueness assumed')+'.','',
   '| Field | Recommended type | Nullable |','| --- | --- | --- |']
  for name,f in t['fields'].items():specs.append(f"| {name}{' [only if '+f['enabled_if']+']' if f.get('enabled_if') else ''} | {f['type']} | {'yes' if f['nullable'] else 'no'} |")
  specs += ['', '**Foreign keys:**','']
  for fk in t['foreign_keys']:
   specs.append('- ('+', '.join(fk['columns'])+') → '+fk['target']+'('+', '.join(fk['target_columns'])+'); RESTRICT. '+fk['basis']+(' [Only if '+fk['enabled_if']+' enabled.]' if fk.get('enabled_if') else ''))
  specs += ['', '**Checks / approval dependencies:**','']+['- '+c for c in t['checks']]
  specs += ['', '**Index candidates beyond existing keys:** '+('; '.join('('+', '.join(x['columns'])+')'+(' [conditional]' if x.get('enabled_if') else '') for x in t['indexes']) or 'PK/unique coverage is sufficient for the declared initial paths')+'.','']
 specs += ['## Operational workflow and analytics compatibility','',
 'Approved explicit Add/Record/Edit actions can select canonical children, source-scoped categories and current associations. Repeated questionnaires create new responses; existing scores are not overwritten. Separate daily/service, support and ADL grains prevent invalid combined denominators. Submission context is retained historically even if child program changes. Staging/reconciliation shows unresolved rows separately from approved analytic facts. Header-only fields or archived summaries needed by future entry require an approved projection first.','',
 'The full machine-readable recommendation is [optimized-model-draft.json](evidence/optimized-model-draft.json); source mappings are [source-target-coverage.csv](evidence/source-target-coverage.csv). The revised ER diagram and per-source dictionary link to this document. No statement here indicates tables, policies, indexes or triggers have actually been created.']
 (ROOT/'docs/11-optimized-data-model.md').write_text('\n'.join(specs)+'\n')
 # Mermaid: all planned tables, external managed auth, domain FKs; common audit FKs omitted for readability.
 lines=['erDiagram']
 for t in tables:
  lines.append('    '+t['name'].upper()+' {')
  fkcols={c for fk in t['foreign_keys'] for c in fk['columns']}
  selected=list(dict.fromkeys(t['primary_key']+[c for c in t['fields'] if c not in {'created_at','updated_at','created_by','updated_by','actor_ref'} and not c.endswith('_vocabulary')]))[:9]
  for c in selected:
   kind=t['fields'][c]['type'];keys=[]
   if c in t['primary_key']:keys.append('PK')
   if c in fkcols:keys.append('FK')
   lines.append('        '+kind+' '+c+(' '+','.join(keys) if keys else ''))
  lines.append('    }')
 lines += ['    AUTH_USERS {','        uuid id PK','    }']
 for t in tables:
  grouped={}
  for fk in t['foreign_keys']:
   if fk['columns'] in [['created_by'],['updated_by']]:continue
   key=(fk['target'],fk.get('enabled_if'));grouped.setdefault(key,[]).append(fk)
  for (target,gate),fks in grouped.items():
   src='AUTH_USERS' if target=='auth.users' else target.upper();dest=t['name'].upper()
   optional=all(any(t['fields'][c]['nullable'] for c in f['columns']) for f in fks)
   left='o|' if optional else '||';right='o|' if set(t['primary_key'])==set(fks[0]['columns']) else 'o{'
   relation='..' if gate else '--'
   label='conditional_typed_origin' if gate else ('scoped_vocabularies' if target=='reference_values' else 'typed_origin' if t['name']=='source_provenance' else 'references')
   lines.append('    '+src+' '+left+relation+right+' '+dest+' : '+label)
 diagram='# Stage 2 — Revised draft ER diagram\n\n**DRAFT, not an implemented database.** Seventeen proposed tables: sixteen core and conditional ACTIVITY_LOGS. AUTH_USERS is Supabase-managed and excluded from that count. Common audit FKs to AUTH_USERS are omitted for readability; full fields/keys are in the model specification. Grouped lookup edges represent separate vocabulary-scoped FKs. Optional target edges in SOURCE_PROVENANCE are mutually exclusive per row, not simultaneous links to every entity. A dotted edge marks the optional activity extension.\n\n```mermaid\n'+'\n'.join(lines)+'\n```\n\nCurated attendance requires resolved identity/date; unresolved source strings are retained in SOURCE_RECORDS rather than falsely becoming valid FKs. Questionnaire pair and answer-definition relationships are proposed constraints based on observed evidence, still subject to analyst approval. Child-to-caregiver and repeated-response cardinalities describe the proposed capacity, not proof of existing person scope or longitudinal behavior.\n\nFor the 16-table variant omit ACTIVITY_LOGS and its SOURCE_PROVENANCE activity pointer/FK/index/target group as one activation unit. See [full optimized model](11-optimized-data-model.md), [comparison](12-data-model-comparison-matrix.md) and [original 12-entity diagram](archive/stage1-er-diagram.md). Diagram syntax/reference checks do not validate business rules or prove rendered layout quality.\n'
 (ROOT/'docs/07-entity-relationship-diagram.md').write_text(diagram)
 print('Rendered raw/organized model, full table specification and revised ER diagram.')

if __name__=='__main__':main()
